<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import { api, onDocumentReorganizeComplete, onDocumentReorganizeError, type DocumentTask } from '../services/tauri';
import { projectStore } from '../stores/project';
import { loadPromptTemplates } from '../data/promptTemplates';
import { notify } from '../stores/ui';
const files=ref<string[]>([]), series=ref(false), running=ref(false), outputDir=ref(''), status=ref('');
const templates=ref(loadPromptTemplates()), selected=ref('extract'), provider=ref('gemini'), modelName=ref('gemini-2.5-flash'), tasks=ref<DocumentTask[]>([]);
const prompt=computed(()=>templates.value.find(t=>t.id===selected.value)?.content||'');
async function refresh(){if(projectStore.project)tasks.value=await api.listDocumentTasks(projectStore.project.id)}
watch(()=>projectStore.project?.id,refresh,{immediate:true});
async function pick(){const picked=await api.pickDocumentFiles();if(picked?.length)files.value=[...new Set([...files.value,...picked])];}
async function pickOutput(){const path=await api.pickExportDir();if(path)outputDir.value=path}
async function run(){if(!projectStore.project||!files.value.length)return;running.value=true;status.value='已创建整理任务，正在处理…';try{await api.runDocumentReorganize(projectStore.project.id,files.value,prompt.value,provider.value,modelName.value,series.value,outputDir.value||undefined);files.value=[]}catch(e){running.value=false;status.value=`无法启动：${e}`;notify(status.value,'error')}}
async function open(path:string){try{await api.openFile(path)}catch(e){notify(`打开失败：${e}`,'error')}} async function reveal(path:string){try{await api.showInFolder(path)}catch(e){notify(`定位失败：${e}`,'error')}}
let off1:(()=>void)|undefined,off2:(()=>void)|undefined;onMounted(async()=>{off1=await onDocumentReorganizeComplete(async()=>{running.value=false;status.value='整理完成';await refresh();notify('文档重整完成','success')});off2=await onDocumentReorganizeError(async e=>{running.value=false;status.value=`整理失败：${e}`;await refresh();notify(status.value,'error',8000)})});onUnmounted(()=>{off1?.();off2?.()});
</script>
<template><div class="doc-view"><header><div><span>DOCUMENT STUDIO</span><h1>文档重整工作台</h1><p>把 TXT、Markdown、SRT、PDF 重新组织成更易读、更可用的知识文档。任务与结果在本页持续保留。</p></div><small>{{ status }}</small></header><section class="create"><div class="section-title"><b>新建整理任务</b><button @click="pick">选择文档</button></div><div v-if="files.length" class="picked"><span v-for="(f,i) in files" :key="f">{{ f.split(/[/\\]/).pop() }} <button @click="files.splice(i,1)">×</button></span></div><div v-else class="hint">尚未选择资料；可一次选择多份 TXT、MD、SRT 或 PDF。</div><div class="fields"><label>提示词模板<select v-model="selected"><option v-for="t in templates" :key="t.id" :value="t.id">{{t.title}}</option></select></label><label>整理服务<select v-model="provider"><option value="gemini">Gemini</option><option value="custom">自定义 OpenAI 兼容</option></select></label><label>模型<select v-if="provider==='gemini'" v-model="modelName"><option value="gemini-2.5-flash">Gemini 2.5 Flash（默认）</option><option value="gemini-2.0-flash">Gemini 2.0 Flash</option></select><input v-else v-model="modelName" placeholder="留空使用设置模型"/></label><label>输出目录<div><input v-model="outputDir" readonly placeholder="默认：下载 / 项目名称 / 文档重整"/><button @click="pickOutput">选择</button></div></label></div><label class="series"><input v-model="series" type="checkbox"/><span><b>系列课程整理</b><small>合并本次所有资料，按全新课程大纲和章节输出一份文档。</small></span></label><footer><div class="prompt"><b>本次提示词</b><span>{{ prompt }}</span></div><button class="run" :disabled="running||!files.length" @click="run">{{running?'整理中…':series?'合并并重整':'开始整理'}}</button></footer></section><section class="jobs"><div class="section-title"><div><b>整理任务与结果</b><small>{{tasks.length}} 条记录</small></div><button @click="refresh">刷新</button></div><div v-if="tasks.length" class="job-list"><article v-for="task in tasks" :key="task.id"><span class="dot" :class="task.status"/><div class="job-main"><b>{{task.name}}</b><small>{{task.series?'系列课程 · ':''}}{{task.model||'默认模型'}} · {{task.created_at}}</small><p v-if="task.error" class="error">{{task.error}}</p></div><span class="state">{{task.status==='running'?'整理中':task.status==='done'?'已完成':'失败'}}</span><div class="actions"><button v-if="task.output_path" @click="open(task.output_path)">打开</button><button v-if="task.output_path" @click="reveal(task.output_path)">定位</button></div></article></div><div v-else class="hint">提交后会在这里显示文档重整任务及可打开的结果。</div></section></div></template>
<style scoped>.doc-view{max-width:1040px;margin:auto;display:grid;gap:16px}.doc-view>header{display:flex;justify-content:space-between;gap:20px;align-items:end}.doc-view>header span{font:700 10px var(--font-mono);letter-spacing:.14em;color:var(--accent)}h1{margin:4px 0;font:700 24px var(--font-display)}header p,header small{font-size:12px;color:var(--text-3)}.create,.jobs{display:grid;gap:14px;padding:18px;border:1px solid var(--border);border-radius:12px;background:var(--surface)}.section-title{display:flex;justify-content:space-between;align-items:center;gap:12px}.section-title b{font-size:14px}.section-title small{margin-left:8px;font-size:11px;color:var(--text-3)}button{cursor:pointer}.section-title>button,.fields button{padding:7px 10px;border:1px solid var(--border);border-radius:7px;background:var(--surface);color:var(--text-2);font-size:12px}.picked{display:flex;flex-wrap:wrap;gap:6px}.picked span{padding:5px 8px;border-radius:5px;background:var(--accent-bg);font-size:11px}.picked button{margin-left:4px;border:0;background:none;color:var(--error)}.hint{padding:18px;border:1px dashed var(--border);border-radius:8px;text-align:center;color:var(--text-3);font-size:12px}.fields{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.fields label{display:grid;gap:4px;font-size:11px;color:var(--text-3)}.fields input,.fields select{width:100%;padding:8px;border:1px solid var(--border);border-radius:7px;background:var(--bg);color:var(--text-1)}.fields label>div{display:flex;gap:5px}.series{display:flex;gap:9px;padding:10px;border-radius:8px;background:var(--accent-bg);font-size:12px}.series small{display:block;margin-top:2px;color:var(--text-3)}footer{display:flex;justify-content:space-between;gap:16px;align-items:center}.prompt{display:grid;gap:3px;min-width:0}.prompt b{font-size:11px}.prompt span{max-width:700px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11px;color:var(--text-3)}.run{padding:9px 14px;border:0;border-radius:8px;background:var(--accent);color:#fff;font-weight:700;white-space:nowrap}.run:disabled{opacity:.45}.job-list{display:grid;gap:5px}.job-list article{display:flex;align-items:center;gap:10px;padding:11px;border:1px solid var(--border-soft);border-radius:8px;background:var(--bg)}.dot{width:8px;height:8px;border-radius:50%;background:var(--neutral-4)}.dot.running{background:var(--accent)}.dot.done{background:var(--success)}.dot.error{background:var(--error)}.job-main{display:grid;gap:2px;min-width:0;flex:1}.job-main b{font-size:12px}.job-main small,.state{font-size:11px;color:var(--text-3)}.error{color:var(--error);font-size:11px}.actions{display:flex;gap:5px}.actions button{border:0;background:none;color:var(--accent);font-size:12px}@media(max-width:800px){.fields{grid-template-columns:1fr 1fr}.doc-view>header,footer{align-items:start;flex-direction:column}}@media(max-width:500px){.fields{grid-template-columns:1fr}.job-list article{align-items:flex-start;flex-wrap:wrap}.actions{margin-left:18px}}</style>
